		names.clear();
		knownLoggedNames.clear();
		pending.clear();
		kills.reset();
		overlay.clear();
		sounds.reset();
		gate.reset();
		cox.reset();
		recentLoot.clear();
		sequence = 0;
		notificationStarted = false;
		replacedNotification = null;
		replacedItem = null;
		notifiedUnlocks.clear();
		lastKcTick = -1;
		lastAudioGroup = -1;
		lastLootSource = null;
		lastLootTick = -1;
		lastLootGroup = -1;
